'use strict';

var ip = exports;

ip.isPrivate = function(addr) {
  return /^(::f{4}:)?10\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})$/i.test(addr) ||
    /^(::f{4}:)?192\.168\.([0-9]{1,3})\.([0-9]{1,3})$/i.test(addr);
};

ip.isLoopback = function(addr) {
  return /^(::f{4}:)?127\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})/.test(addr) ||
    /^::1$/.test(addr);
};

ip.isPublic = function(addr) {
  return !ip.isPrivate(addr) && !ip.isLoopback(addr);
};

ip.toLong = function(addr) {
  var n = 0;
  addr.split('.').forEach(function(octet) {
    n <<= 8;
    n += parseInt(octet, 10);
  });
  return n >>> 0;
};

ip.isV4Format = function(ip) {
  return /^(\d{1,3}\.){3,3}\d{1,3}$/.test(ip);
};

ip.normalize = function(ip) {
  var trimmed = ip.trim();
  return trimmed.toLowerCase();
};
